import Foundation
import CoreGraphics
var passed=0,failed=0
func check(_ n:String,_ ok:Bool){if ok{passed+=1;print("PASS \(n)")}else{failed+=1;print("FAIL \(n)")}}
let r=GameConfig.Arena.radius,geo=ArenaGeometry.twinChannels,spark=CGPoint(x:0.43*GameConfig.Arena.radius,y:0)
guard let p=RailspikeState.choosePlan(from:CGPoint(x:spark.x,y:-0.7*r),player:spark,bodyRadius:14,geometry:geo,radius:r)else{fatalError("R0 valid plan")}
check("R1 axis",p.direction.x==0 && abs(p.direction.y)==1 && p.anchor.x==spark.x)
check("R2 range",p.range<=1.2*r && p.range>abs(spark.y-p.anchor.y))
check("R3 clear corridor",!geo.segmentBlockedExact(p.anchor,p.end,travelRadius:GameConfig.Railspike.boltRadius))
check("R4 circle endpoint",p.end.length+GameConfig.Railspike.boltRadius<=r+0.001)
check("R5 same lane",RailspikeState.choosePlan(from:CGPoint(x:-spark.x,y:0),player:spark,bodyRadius:14,geometry:geo,radius:r)==nil)
check("R6 crossing not lane",RailspikeState.choosePlan(from:p.anchor,player:.zero,bodyRadius:14,geometry:geo,radius:r)==nil)
check("R7 denied anchor",RailspikeState.choosePlan(from:p.anchor,player:CGPoint(x:r*0.95,y:0),bodyRadius:14,geometry:geo,radius:r)==nil)
for sign:CGFloat in [-1,1]{for y:CGFloat in [-0.3,0,0.3]{let q=CGPoint(x:sign*0.43*r,y:y*r);check("R8 local sample \(sign) \(y)",RailspikeState.choosePlan(from:CGPoint(x:q.x,y:-0.75*r),player:q,bodyRadius:14,geometry:geo,radius:r) != nil)}}
var s=RailspikeState();s.step(0,disabled:false,atAnchor:true,candidate:p)
check("R9 full tell starts",s.phase == .windup && s.remaining==1 && s.consumeLaunch()==nil)
s.step(0.999,disabled:false,atAnchor:true,candidate:p);check("R10 no early bolt",s.consumeLaunch()==nil)
s.step(0.002,disabled:false,atAnchor:true,candidate:p);check("R11 first bolt",s.consumeLaunch()==p && s.shots==1)
check("R12 no duplicate",s.consumeLaunch()==nil)
s.step(0.449,disabled:false,atAnchor:true,candidate:p);check("R13 full interval",s.consumeLaunch()==nil)
s.step(0.002,disabled:false,atAnchor:true,candidate:p);check("R14 second bolt",s.consumeLaunch()==p && s.shots==2 && s.phase == .recovery)
check("R15 no third",s.consumeLaunch()==nil)
s.step(1.299,disabled:false,atAnchor:true,candidate:p);check("R16 recovery holds",s.phase == .recovery)
s.step(0.002,disabled:false,atAnchor:true,candidate:p);s.step(0,disabled:false,atAnchor:true,candidate:p);check("R17 cycle holds",s.phase == .seek)
s.step(5,disabled:false,atAnchor:true,candidate:p);check("R18 rearm",s.phase == .windup)
s.step(0.1,disabled:false,atAnchor:true,candidate:RailspikePlan(anchor:.zero,direction:CGPoint(x:1,y:0),range:50));check("R19 world lock",s.plan==p)
var huge=RailspikeState();huge.step(100,disabled:false,atAnchor:true,candidate:p);check("R20 long frame full tell",huge.phase == .windup && huge.consumeLaunch()==nil)
huge.step(100,disabled:false,atAnchor:true,candidate:p);huge.step(100,disabled:false,atAnchor:true,candidate:p);check("R21 no catchup bunch",huge.consumeLaunch()==p && huge.consumeLaunch()==nil)
huge.step(0,disabled:false,atAnchor:true,candidate:p);check("R22 interval starts at dispatch",huge.consumeLaunch()==nil)
huge.step(0.46,disabled:true,atAnchor:true,candidate:p);check("R23 disable second",huge.consumeLaunch()==nil && huge.plan==nil)
var badClock=RailspikeState();badClock.step(.nan,disabled:false,atAnchor:true,candidate:p);badClock.step(-1,disabled:false,atAnchor:true,candidate:p);check("R24 bad clock inert",badClock.phase == .seek)
func armed()->RailspikeNode{let n=RailspikeNode();n.position=p.anchor;_=n.approachGoal(player:spark,geometry:geo,radius:r,disabled:false);n.chase(target:spark,deltaTime:0);return n}
for flag in 0..<6{let n=armed();n.chase(target:spark,deltaTime:1.01);if flag==0{n.isDying=true};if flag==1{n.isFrozen=true};if flag==2{n.isStunned=true};if flag==3{n.isVoidTrapped=true};if flag==4{n.isFeared=true};if flag==5{n.position.x+=20};check("R25 fresh cancellation \(flag)",n.consumeLaunch()==nil && n.attack.plan==nil)}
let second=armed();second.chase(target:spark,deltaTime:1.01);_=second.consumeLaunch();second.chase(target:spark,deltaTime:0.46);second.isDying=true;check("R26 queued second death",second.consumeLaunch()==nil)
let hidden=RailspikeNode();hidden.position=p.anchor;hidden.canBeginTell=false;_=hidden.approachGoal(player:spark,geometry:geo,radius:r,disabled:false);hidden.chase(target:spark,deltaTime:0);check("R27 offscreen no tell",hidden.attack.phase == .seek)
let slow=RailspikeNode();slow.position=CGPoint(x:spark.x,y:-0.7*r);let start=slow.position;_=slow.approachGoal(player:spark,geometry:geo,radius:r,disabled:false);slow.chase(target:p.anchor,deltaTime:0.1,globalSlow:0.5);check("R28 approach slow",abs(slow.position.distance(to:start)-5.2)<0.001)
let a=ChannelAttackSchedule();check("R29 collection before grant",!a.request(.railspike) && !a.request(.tollkeeper));a.beginFrame(0,railBolts:0)
check("R30 initial priority",!a.request(.railspike) && a.request(.tollkeeper));check("R31 exclusivity",!a.request(.railspike))
a.finish(.tollkeeper);a.beginFrame(10,railBolts:0);check("R32 long frame preserves new gap",a.owner==nil && a.gap==0.35 && !a.request(.railspike))
a.beginFrame(0.349,railBolts:0);check("R33 gap holds",!a.request(.railspike));_=a.request(.tollkeeper);a.beginFrame(0.002,railBolts:0);check("R34 next role when both ready",!a.request(.tollkeeper) && a.request(.railspike))
a.finish(.railspike);a.beginFrame(5,railBolts:1);check("R35 dead shooter bolt retains",a.owner == .railspike && !a.request(.tollkeeper))
a.beginFrame(0,railBolts:0);check("R36 removal starts gap",a.owner==nil && a.gap==0.35)
_=a.request(.tollkeeper);_=a.request(.railspike);a.beginFrame(0.36,railBolts:0);check("R37 alternating",!a.request(.railspike) && a.request(.tollkeeper))
a.reset();check("R38 reset",a.owner==nil && a.gap==0 && a.next == .tollkeeper)
for reverse in [false,true]{let q=ChannelAttackSchedule();if reverse{_=q.request(.tollkeeper);_=q.request(.railspike)}else{_=q.request(.railspike);_=q.request(.tollkeeper)};q.beginFrame(0,railBolts:0);check("R39 order independence \(reverse)",!q.request(.railspike) && q.request(.tollkeeper))}
let stale=ChannelAttackSchedule();_=stale.request(.railspike);stale.beginFrame(0,railBolts:0);stale.beginFrame(0,railBolts:0);_=stale.request(.tollkeeper);stale.beginFrame(0,railBolts:0);check("R40 stale grant expires",stale.request(.tollkeeper))
let cancelled=ChannelAttackSchedule();let pre=armed();pre.schedule=cancelled;_=cancelled.request(.railspike);cancelled.beginFrame(0,railBolts:0);_=cancelled.request(.railspike);pre.cancelAttack();cancelled.beginFrame(0,railBolts:0);check("R41 prelaunch cancellation releases",cancelled.owner==nil && cancelled.gap==0.35)
let live=ChannelAttackSchedule();let gun=RailspikeNode();gun.position=p.anchor;gun.schedule=live;_=gun.approachGoal(player:spark,geometry:geo,radius:r,disabled:false);gun.chase(target:spark,deltaTime:0);live.beginFrame(0,railBolts:0);gun.chase(target:spark,deltaTime:0);gun.chase(target:spark,deltaTime:1.01);_=gun.consumeLaunch();live.beginFrame(0.1,railBolts:0)
check("R42 removed first retains second",live.owner == .railspike);gun.chase(target:spark,deltaTime:0.46);_=gun.consumeLaunch();live.beginFrame(0.1,railBolts:1);check("R43 second bolt retains",live.owner == .railspike)
let blocking=ChannelAttackSchedule();_=blocking.request(.railspike);blocking.beginFrame(0,railBolts:0);_=blocking.request(.railspike)
let toll=TollkeeperNode();toll.position=spark;_=toll.approachGoal(player:spark,geometry:geo,radius:r,disabled:false);toll.chase(target:spark,deltaTime:0);toll.chase(target:spark,deltaTime:0.91);toll.chase(target:spark,deltaTime:0.36);toll.chase(target:spark,deltaTime:1.21)
check("R44 cooldown setup",toll.attack.phase == .seek && toll.attack.cooldown>0);toll.schedule=blocking;_=toll.approachGoal(player:spark,geometry:geo,radius:r,disabled:false);toll.chase(target:spark,deltaTime:2)
check("R45 cooldown crossing needs lease",toll.attack.phase == .seek && blocking.owner == .railspike)
let sc=GameScene();let cannon=armed();sc.worldNode.children=[cannon];sc.waveManager.elapsedTime=60;cannon.chase(target:spark,deltaTime:1.01);sc.processRailspikeLaunches();sc.processRailspikeLaunches()
check("R46 scene dispatch once",sc.enemyProjectiles.count==1 && sc.channelRailBolts.count==1)
check("R47 ordinary tuning",sc.enemyProjectiles.first?.damage==21 && sc.enemyProjectiles.first?.speed==300 && sc.enemyProjectiles.first?.direction.x==0)
cannon.chase(target:spark,deltaTime:0.46);sc.processRailspikeLaunches();check("R48 real second",sc.enemyProjectiles.count==2)
for phase:GameScene.State in [.paused,.levelUp,.dead]{let hold=GameScene();hold.gameState=phase;let c=armed();c.chase(target:spark,deltaTime:1.01);hold.worldNode.children=[c];hold.processRailspikeLaunches();check("R49 inactive \(phase)",hold.enemyProjectiles.isEmpty && c.attack.shots==0)}
let pin=GameScene();let c=armed();c.chase(target:spark,deltaTime:1.01);pin.worldNode.children=[c];pin.repulseFlights[ObjectIdentifier(c)]=true;pin.processRailspikeLaunches();check("R50 airborne",pin.enemyProjectiles.isEmpty && c.attack.plan==nil)
sc.enemyProjectiles.removeAll();sc.updateChannelAttacks(0);check("R51 actual cleanup",sc.channelRailBolts.isEmpty)
let sp=GameScene();sp.waveManager.elapsedTime=45;for _ in 0..<80{sp.spawnTwinChannelsEnemy()};check("R52 spawn cap",sp.enemies.filter{$0 is RailspikeNode}.count==1 && sp.enemies.filter{$0 is TollkeeperNode}.count==1);check("R53 spawn timestamps",sp.channelRailspikeLastSpawn==45 && sp.channelTollkeeperLastSpawn==45)
let old=GameScene();old.isTwinChannels=false;old.worldNode.children=[armed()];old.processRailspikeLaunches();check("R54 preview isolation",old.enemyProjectiles.isEmpty)
check("R55 actual shared scheduler wiring",sp.enemies.compactMap{$0 as? RailspikeNode}.first?.schedule === sp.channelAttacks && sp.enemies.compactMap{$0 as? TollkeeperNode}.first?.schedule === sp.channelAttacks)
print("Railspike: \(passed) passed / \(failed) failed");exit(failed==0 ? 0 : 1)
